sc_cat_item_producer.script:
var endPoint = "https://" + producer.contrast_url + "/Contrast/api/sast/organizations/" + producer.organization_id + "/projects";
var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
r.setEndpoint(endPoint);
r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
r.setRequestHeader('API-Key', producer.api.getDecryptedValue()); //Load API-Key
r.setRequestHeader('Authorization', producer.authorization); //Load Authorization
r.setHttpTimeout(30000);

var rtn = r.execute(); // Execute API

if (rtn.getStatusCode() == 200) {

    updateAPI();
} else {
    var r1 = new sn_ws.RESTMessageV2();
    r1.setEndpoint("https://" + producer.contrast_url + "/Contrast/api/ng/" + producer.organization_id + "/applications/");
    r1.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
    r1.setRequestHeader('API-Key', producer.api.getDecryptedValue()); //Load API-Key
    r1.setRequestHeader('Authorization', producer.authorization); //Load Authorization
    r1.setRequestHeader('Accept', "application/json");
    r1.setHttpMethod('GET');
    r1.setHttpTimeout(30000);

    var rtn1 = r1.execute(); // Execute API
    if (rtn1.getStatusCode() == 200) {
        updateAPI();
    } else {
        gs.addErrorMessage("Authentication Failed");
        producer.redirect = "com.glideapp.servicecatalog_cat_item_view.do?v=1&sysparm_id=69479e0197cb2a506b73be6de053afbb";
    }

}


function updateAPI() {
    var configGR = new GlideRecord("sn_sec_int_impl_config");
    configGR.addEncodedQuery("sys_scope.name=Contrast Security Application Vulnerability Integration");

    configGR.query();
    while (configGR.next()) {
        switch (configGR.configuration.getDisplayValue()) {
            case "api_key":
                configGR.value = producer.api.getDecryptedValue();
                //configGR.password_value=producer.api;
                break;
            case "org_id":
                configGR.value = producer.organization_id;
                break;
            case "authorization":
                configGR.value = producer.authorization;
                break;
            case "contrast_url":
                configGR.value = producer.contrast_url;
                break;
            case "manage_false_positives_in_snow":
                if (producer.manage_false_positives_in_servicenow == 'true') {
                    configGR.value = true;
                } else {
                    configGR.value = false;
                }
                break;
            case "manage_exceptions_in_snow":
                if (producer.manage_exceptions_in_servicenow == 'true') {
                    configGR.value = true;
                } else {
                    configGR.value = false;
                }
                break;
        }
		configGR.setWorkflow(false);
        configGR.update();
        producer.redirect = "com.glideapp.servicecatalog_cat_item_view.do?v=1&sysparm_id=69479e0197cb2a506b73be6de053afbb";
    }
}
